#!/bin/bash
# shellcheck disable=SC2015
set -eEuo pipefail
# stimmeDe (commit64): deutsche MBROLA-Stimme mb-de7, sonst espeak-ng -v de, sonst espeak -v de.
# Kein apt, kein Netzabruf, kein Umbau von PipeWire oder ALSA.
# Voraussetzung ist der installierte commit63. Bestaetigte Pi-Basis: lage_pages.py trim.
# Die Speicher-Kuerzung wird nicht angefasst und nicht wieder eingefuegt.
# Aufruf: bash apply-commit64.sh commit64 [dry-run]
# Simulation: DASH_PORT=5093 C61_SIM_DIR C61_SIM_W C61_FAKE_HM C61_RETRY_S C61_WAIT_S C61_SIM_NOMUT C61_READY_S
COMMIT_ARG="${1:-unbekannt}"
MODE_ARG="${2:-}"
case "$MODE_ARG" in ""|dry-run|--dry-run|dryrun|trockenlauf) ;; *) echo "STOP: unbekannter zweiter Parameter '$MODE_ARG' (erlaubt: dry-run) - nichts geaendert"; exit 1;; esac
DRY=0; [[ -n "$MODE_ARG" ]] && DRY=1
DASH_DIR="/home/fmg/prepper-dashboard"
W=/tmp/commit64-apply
NM=commit64
MK=stimmeDe
SIM=0; [[ -n "${DASH_PORT:-}" && "${DASH_PORT:-}" != 5000 ]] && SIM=1
if [[ "$SIM" == 1 ]]; then DASH_DIR="${C61_SIM_DIR:-$DASH_DIR}"; W="${C61_SIM_W:-$W}"; fi
VPY="$DASH_DIR/venv/bin/python"
SPY=/usr/bin/python3
TS=$(date +%Y%m%d-%H%M%S)
KEEP_LAST=3
SINGLE=(dashboard.py prepper_docs.py)
declare -A ALT=(
  [dashboard.py]=8a055ad3ed0619f681e2575c5ad588c3a28330eba1c00daab46d1cde46e28908
  [prepper_docs.py]=8f9983737e5217a4dbaecbc8764d6889cff10f0a82a41fe7b97e1bf9671e3751
)
declare -A NEU=(
  [dashboard.py]=5858908eaf6498bbcb737ad4791adb0bba0e4c7f4be0657f0bb31cdbef157a1d
  [prepper_docs.py]=36804387c50cba2b2021c71eaef1babc7aee85ebb0042e0849fa2267013d9937
)
LAGE_TRIM=6b10e3bae7118d9519760b492220e88a5caf2e9dc99e9ed8db096eb911d0e778
LAGE_FULL=d268d324f4fd55a53cb7ee1919e3fb399e2c4ca0a7733780c9bf977b0fee2fca
LAGE62_TRIM=5185cfefaf5dbc1c30ae6349278f1fe43832c4fed92fe7619484ae2ac7ec7e74
LAGE62_FULL=536780ba4b89a69a34183d20a802251ec5f8dbc4f19b7a6a8d95c516e2e13a9f
UPS_KEEP=b2e491e36a9a1861de4c609f80a613f9b824e4f6f52319c50e5c5a87252ddcf8
declare -A KEEP=(
  [gas_saison.py]=1a258f195e59528b23841e350fdf505959d461f7779c7969ef0264980ee875d4
  [prepper_sdr.py]=b879ab56f4ac4736
  [sdr_manager.py]=5a26efff608bf541
  [database.py]=2754d0bdddca9400
  [prepper_evlog.py]=8bffd396972b60fa
)
DOCS="$DASH_DIR/docs"
PHASE=vorher
FINISHED=0
RESTARTED=0
STOPPED=0
RB_DONE=0
INST=()
VARIANT=""
LH0=""
ERRLN=""; ERRCMD=""
trap 'ERRLN=$LINENO; ERRCMD=$BASH_COMMAND' ERR
stop() { STOPPED=1; echo "STOP: $1 - nichts geaendert"; exit 1; }
CFG_PORT=$(sed -n 's/^PORT[[:space:]]*=[[:space:]]*\([0-9][0-9]*\).*/\1/p' "$DASH_DIR/config.py" 2>/dev/null | head -1 || true)
PORT="${DASH_PORT:-${CFG_PORT:-5000}}"
if ! [[ "$PORT" =~ ^[0-9]+$ ]]; then stop "Dashboard-Port unklar ($PORT)"; fi
if [[ "$PORT" == "8080" ]]; then stop "Port 8080 ist kiwix-serve, nicht das Dashboard"; fi
if [[ "$SIM" == 1 && "$PORT" != "5093" ]]; then stop "Simulation nur auf Port 5093 (jetzt $PORT)"; fi
if [[ "$SIM" == 0 && "$PORT" != "5000" ]]; then stop "Echter Lauf nur auf Port 5000 (jetzt $PORT)"; fi
B="http://127.0.0.1:${PORT}"
CURL=(curl --compressed -s --connect-timeout 3 --max-time 40)
[[ -x "$VPY" ]] || VPY=python3
[[ -x "$SPY" ]] || SPY=python3
for t in python3 sha256sum curl flock cp mv cmp stat date timeout nice base64; do command -v "$t" >/dev/null 2>&1 || stop "Werkzeug $t fehlt"; done
s16() { sha256sum "$1" | cut -c1-16; }
sfull() { sha256sum "$1" | cut -d' ' -f1; }
on_exit() {
  local ec=$?
  if [[ $ec -ne 0 && $FINISHED -eq 0 ]]; then
    if [[ "$PHASE" == vorher ]]; then
      [[ -n "$ERRLN" && "$STOPPED" == 0 ]] && echo "ABBRUCH: unerwarteter Fehler (Exit $ec) in Zeile $ERRLN, Befehl: $(echo "$ERRCMD" | cut -c1-400) - es wurde noch nichts geaendert"
    elif [[ "$PHASE" == installiert && "$RB_DONE" == 0 ]]; then
      echo "ABBRUCH: unerwarteter Fehler (Exit $ec) in Zeile ${ERRLN:-?}, Befehl: $(echo "${ERRCMD:-?}" | cut -c1-400) - Rollback"
      rb "unerwarteter Fehler" || true
    fi
  fi
}
trap on_exit EXIT
echo "=== $MK apply ($COMMIT_ARG$([[ "$DRY" == 1 ]] && echo ", TROCKENLAUF")): MBROLA mb-de7 mit espeak-Rueckfall, Port $PORT, Ordner $DASH_DIR ==="
echo "Bestaetigte Basis auf dem Pi: commit63, lage_pages.py trim ${LAGE_TRIM:0:16}. Diese Datei wird nicht geschrieben."
umask 022
mkdir -p "$(dirname "$W")"
exec 9>"$W.lock"
flock -n 9 || stop "ein anderer $NM-Lauf ist aktiv (Sperre $W.lock)"
rm -rf "$W" && mkdir -p "$W/neu" "$W/alt" "$W/html" && chmod 700 "$W"
python3 - "$W/neu" << 'MK_PAY_EOF'
import base64, hashlib, os, sys
dest = sys.argv[1]
os.makedirs(dest, exist_ok=True)
raw = {
    'dashboard.py': '',
    'prepper_docs.py': '',
}
expect = {
    'dashboard.py': '5858908eaf6498bbcb737ad4791adb0bba0e4c7f4be0657f0bb31cdbef157a1d',
    'prepper_docs.py': '36804387c50cba2b2021c71eaef1babc7aee85ebb0042e0849fa2267013d9937',
}
for name, b64 in raw.items():
    data = base64.b64decode(b64)
    got = hashlib.sha256(data).hexdigest()
    if got != expect[name]:
        sys.stderr.write("FEHLER sha256 %s %s\n" % (name, got))
        sys.exit(1)
    tmp = os.path.join(dest, name + ".tmp")
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, os.path.join(dest, name))
print("OK Nutzlast sha256 geprueft (%d Dateien)" % len(raw))
MK_PAY_EOF
EXPECT_GRD='fd67b6423e443c6d500f1cb7ea8f42ad5528812b47dacb18e0e7c32e6b22c859'
cat > "$W/guard.py" << 'MK_GRD_EOF'
#!/usr/bin/env python3
"""guard64.py check ALT NEU VAR | mutate ALT NEU VAR
VAR ist trim (auf dem Pi bestaetigt) oder full.
Prueft die Ansage. USV, Abschaltung und die Speicher-Kuerzung bleiben."""
import sys

SHUT = "Abschaltung bei 20 % oder 5 min · upsmon aktiv"
LOW = "USVA_LOW_S = 300"
OB = "OB_CONFIRM_S = 20"


def read(path):
    with open(path, encoding="utf-8") as f:
        return f.read()


def routes(src):
    return src.count("@app.route("), src.count("add_url_rule(")


def chk(alt_dash, neu, variant):
    err = []
    d, docs, um, p = neu["dashboard.py"], neu["prepper_docs.py"], neu["ups_manager.py"], neu["lage_pages.py"]
    if 'AU_VOICE_MB = "mb-de7"' not in d:
        err.append("MBROLA-Stimme mb-de7 fehlt")
    if 'AU_MBROLA_DB = "/usr/share/mbrola/de7/de7"' not in d:
        err.append("Sprachdatei nicht festgelegt")
    if "getsize(path) >= AU_WAV_MIN" not in d or "AU_WAV_MIN = 1000" not in d:
        err.append("zu kleine WAV-Datei gilt als Ansage")
    if 'if why == "abgebrochen" or aborted():' not in d:
        err.append("Abbruch spricht weiter")
    if d.count('("espeak-ng", "de")') < 2 or d.count('("espeak", "de")') < 1:
        err.append("Rueckfall auf espeak-ng/espeak fehlt")
    if '"mbrola"' not in d.split("T4_KILL_COMM", 1)[-1][:180]:
        err.append("Kill-Switch erfasst mbrola nicht")
    fn = d.split("def _au_synth", 1)[-1].split("def _au_out", 1)[0]
    plan = d.split("def _au_say_plan", 1)[-1].split("def _au_wav_ok", 1)[0]
    if "apt-get" in fn or "urlopen" in fn or "requests." in fn or "http://" in plan or "https://" in plan:
        err.append("Stimme holt etwas aus dem Netz oder installiert Pakete")
    dev = d.split("def _au_devices", 1)[-1].split("def _au_play", 1)[0]
    if "pulse" not in dev or '"default"' not in dev or "Headphones" not in dev:
        err.append("Ausgabeweg geaendert")
    if "AU_VOL_DEFAULT = 80" not in d or "AU_DEDUP_S = 6 * 3600" not in d or "AU_NIGHT = (22, 7)" not in d or "AU_MUTE_MAX_H = 8" not in d:
        err.append("Lautstaerke, Dedup, Nachtruhe oder Stumm geaendert")
    if '"KATASTROPHE": 3' not in d:
        err.append("Vorrang geaendert")
    test_fn = d.split("def _au_api_test", 1)[-1].split("class _AuFakeP", 1)[0]
    if '"mesh": False' not in test_fn:
        err.append("Testalarm kann Mesh setzen")
    if "systemctl restart pipewire" in d or "systemctl restart pipewire-pulse" in d:
        err.append("Audio-System wird umgestellt")
    if OB not in um or LOW not in d or d.count(SHUT) != 3:
        err.append("Abschaltung oder Netzausfall-Schwelle geaendert")
    if 'HOST = "127.0.0.1"' not in um:
        err.append("NUT-Host ist nicht mehr nur lokal")
    if routes(d) != routes(alt_dash):
        err.append("Routen geaendert")
    note = 'get("scenario_note")' in p
    prof = 'get("profile_text")' in p
    if variant == "trim" and (note or prof):
        err.append("Speicher-Kuerzung wurde rueckgaengig gemacht")
    if variant == "full" and not (note and prof):
        err.append("ungekuerzte Speicher-Seite verliert Profil oder Szenariohinweis")
    if "stimmeDe" not in docs or "mbrola-de7" not in docs or "espeak-ng" not in docs:
        err.append("Projektbeschreibung ohne Stimme")
    if "installiert keine Pakete" not in docs and "installiert nichts" not in docs:
        err.append("Projektbeschreibung verschweigt, dass keine Pakete installiert werden")
    if "20 % oder 5 min" not in docs:
        err.append("Doku zur Abschaltung geaendert")
    return err


def main():
    if len(sys.argv) < 5:
        print("Aufruf: guard64.py check|mutate ALT NEU trim|full")
        sys.exit(2)
    cmd, alt, neu, variant = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
    if variant not in ("trim", "full"):
        print("Variante muss trim oder full sein")
        sys.exit(2)
    files = {}
    for name in ("dashboard.py", "prepper_docs.py", "ups_manager.py", "lage_pages.py"):
        files[name] = read("%s/%s" % (neu, name))
    alt_dash = read("%s/dashboard.py" % alt)
    if cmd == "check":
        e = chk(alt_dash, files, variant)
        if e:
            print("\n".join("VERSTOSS " + x for x in e))
            sys.exit(1)
        print("Guard stimmeDe ok: mb-de7 nur mit lokaler Datei, sonst espeak, USV unveraendert, Speicher-Kuerzung bleibt")
        return
    d, docs, um, p = files["dashboard.py"], files["prepper_docs.py"], files["ups_manager.py"], files["lage_pages.py"]

    def put(**kw):
        out = dict(files)
        out.update(kw)
        return out

    lage_bad = p + '\nget("scenario_note")\nget("profile_text")\n' if variant == "trim" else p.replace('get("scenario_note")', 'get("scenario_x")', 1)
    mut = [
        ("Stimme mb-de7 entfernt", put(**{"dashboard.py": d.replace('AU_VOICE_MB = "mb-de7"', 'AU_VOICE_MB = "mb-de1"', 1)})),
        ("Sprachdatei weg", put(**{"dashboard.py": d.replace('AU_MBROLA_DB = "/usr/share/mbrola/de7/de7"', 'AU_MBROLA_DB = ""', 1)})),
        ("leere WAV gilt als Ansage", put(**{"dashboard.py": d.replace("getsize(path) >= AU_WAV_MIN", "getsize(path) >= 0", 1)})),
        ("Abbruch spricht weiter", put(**{"dashboard.py": d.replace('if why == "abgebrochen" or aborted():', "if False:", 1)})),
        ("apt im Stimmweg", put(**{"dashboard.py": d.replace("def _au_synth(", "def _au_synth(\n    'apt-get install mbrola'\n", 1)})),
        ("Netzabruf im Stimmweg", put(**{"dashboard.py": d.replace("def _au_synth(", "def _au_synth(\n    urlopen('http://example.invalid/voice')\n", 1)})),
        ("Lautstaerke-Standard 100", put(**{"dashboard.py": d.replace("AU_VOL_DEFAULT = 80", "AU_VOL_DEFAULT = 100", 1)})),
        ("espeak-ng-Rueckfall fehlt", put(**{"dashboard.py": d.replace('plan.append(("espeak-ng", "de"))', "pass", 1)})),
        ("USV-Schwelle geaendert", put(**{"dashboard.py": d.replace("USVA_LOW_S = 300", "USVA_LOW_S = 60", 1)})),
        ("Kuerzung zurueck" if variant == "trim" else "Profilzeile weg", put(**{"lage_pages.py": lage_bad})),
    ]
    bad = 0
    for name, changed in mut:
        e = chk(alt_dash, changed, variant)
        print(("erkannt  " if e else "UEBERSEHEN ") + name + (": " + e[0] if e else ""))
        if not e:
            bad += 1
    print("Mutationstest stimmeDe: %d/%d erkannt" % (len(mut) - bad, len(mut)))
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
MK_GRD_EOF
echo "$EXPECT_GRD  $W/guard.py" | sha256sum -c - >/dev/null 2>&1 || stop "sha256 von guard.py falsch (Skript beschaedigt oder veraendert - bitte neu laden)"
echo "OK eingebettete Nutzlast und Guard geprueft"
for f in "${SINGLE[@]}" lage_pages.py ups_manager.py "${!KEEP[@]}"; do [[ -f "$DASH_DIR/$f" ]] || stop "$f fehlt im Projektordner $DASH_DIR"; done
NA=0; NN=0; ODD=""
for f in "${SINGLE[@]}"; do
  h=$(sfull "$DASH_DIR/$f")
  if [[ "$h" == "${ALT[$f]}" ]]; then NA=$((NA+1))
  elif [[ "$h" == "${NEU[$f]}" ]]; then NN=$((NN+1))
  else ODD+="$f=${h:0:16} "; fi
done
[[ -z "$ODD" ]] || stop "Stand weicht ab (commit64 setzt den installierten commit63 voraus): ${ODD}"
LH=$(sfull "$DASH_DIR/lage_pages.py")
LH0="$LH"
case "$LH" in
  "$LAGE_TRIM") VARIANT=trim; echo "OK lage_pages.py ist die bestaetigte Kuerzung ${LH:0:16} und bleibt unveraendert";;
  "$LAGE_FULL") VARIANT=full; echo "OK lage_pages.py ist die ungekuerzte commit63-Fassung ${LH:0:16} und bleibt unveraendert. Der bestaetigte Pi-Stand ist trim ${LAGE_TRIM:0:16}.";;
  "$LAGE62_TRIM"|"$LAGE62_FULL") stop "lage_pages.py ${LH:0:16} ist noch der commit62-Stand. Erst commit63 anwenden. Die bestaetigte Basis fuer commit64 ist trim ${LAGE_TRIM:0:16}.";;
  *) stop "lage_pages.py ${LH:0:16} ist weder die bestaetigte Kuerzung ${LAGE_TRIM:0:16} noch die ungekuerzte commit63-Fassung ${LAGE_FULL:0:16}. Bitte den Ist-Hash melden.";;
esac
UH=$(sfull "$DASH_DIR/ups_manager.py")
[[ "$UH" == "$UPS_KEEP" ]] || stop "ups_manager.py ${UH:0:16} ist nicht der commit63-Stand ${UPS_KEEP:0:16}"
KODD=""
for f in "${!KEEP[@]}"; do
  h=$(sfull "$DASH_DIR/$f")
  if [[ "$f" == gas_saison.py ]]; then
    [[ "$h" == "${KEEP[$f]}" ]] || KODD+="$f=${h:0:16} "
  else
    [[ "${h:0:16}" == "${KEEP[$f]}" ]] || KODD+="$f=${h:0:16} "
  fi
done
[[ -z "$KODD" ]] || stop "Unveraenderte Dateien weichen ab: ${KODD}"
if [[ "$NA" == 2 ]]; then STATE=alt; echo "OK Basis commit63, Variante $VARIANT"
elif [[ "$NN" == 2 ]]; then STATE=neu; echo "OK $NM ist schon installiert (Variante $VARIANT), lage_pages.py wird nicht angefasst"
else
  echo "STOP: Mischstand - nichts geaendert."
  for f in "${SINGLE[@]}" lage_pages.py ups_manager.py; do echo "      $f $(sfull "$DASH_DIR/$f" | cut -c1-16)"; done
  STOPPED=1; exit 1
fi
[[ -w "$DASH_DIR" ]] || stop "Projektordner nicht beschreibbar"
"$VPY" -c "import sys; assert sys.version_info >= (3, 9)" 2>/dev/null || stop "Python der venv ($VPY) ist aelter als 3.9 oder nicht startbar"
mkdir -p "$W/alt" "$W/check"
cp "$DASH_DIR/dashboard.py" "$W/alt/dashboard.py"
cp "$W/neu/dashboard.py" "$W/neu/prepper_docs.py" "$W/check/"
cp "$DASH_DIR/ups_manager.py" "$DASH_DIR/lage_pages.py" "$W/check/"
python3 "$W/guard.py" check "$W/alt" "$W/check" "$VARIANT" > "$W/g.log" 2>&1 || { cat "$W/g.log"; stop "Guard $MK meldet Verstoss"; }
echo "OK $(head -1 "$W/g.log")"
MUTS=1; [[ -n "${C61_SIM_NOMUT:-}" && "$SIM" == 1 ]] && { MUTS=0; echo "SIM: Mutationstest uebersprungen"; }
if [[ "$MUTS" == 1 ]]; then
  python3 "$W/guard.py" mutate "$W/alt" "$W/check" "$VARIANT" > "$W/gm.log" 2>&1 || { cat "$W/gm.log"; stop "Mutationstest $MK: eine Veraenderung wurde nicht erkannt"; }
  echo "OK $(grep -E '^Mutationstest' "$W/gm.log")"
  grep -q "UEBERSEHEN" "$W/gm.log" && { cat "$W/gm.log"; stop "Mutationstest enthaelt UEBERSEHEN"; }
fi
for py in "$SPY" "$VPY"; do
  for x in "$W/check/dashboard.py" "$W/check/prepper_docs.py" "$W/check/ups_manager.py" "$W/check/lage_pages.py" "$W/guard.py"; do
    "$py" -W error -c 'import sys; compile(open(sys.argv[1], encoding="utf-8").read(), sys.argv[1], "exec")' "$x" 2>"$W/pyc.log" || { cat "$W/pyc.log"; stop "py_compile $(basename "$x") mit $py meldet Fehler/Warnung"; }
  done
  ( cd "$DASH_DIR" && PYTHONDONTWRITEBYTECODE=1 timeout 90 "$py" -c 'import ups_manager; print(ups_manager.selftest())' ) > "$W/st.log" 2>&1 || { cat "$W/st.log"; stop "Selbsttest ups_manager mit $py fehlgeschlagen"; }
  grep -q "^ups_manager ok" "$W/st.log" || { cat "$W/st.log"; stop "Selbsttest ups_manager ohne ok ($py)"; }
done
echo "OK py_compile und ups_manager-Selbsttest ($SPY und $VPY)"
voice_import() {
  local py log
  rm -rf "$W/try" && mkdir -p "$W/try"
  find "$DASH_DIR" -maxdepth 1 -name '*.py' -exec ln -s {} "$W/try/" \;
  rm -f "$W/try/dashboard.py" "$W/try/prepper_docs.py"
  cp "$W/neu/dashboard.py" "$W/try/dashboard.py"
  cp "$W/neu/prepper_docs.py" "$W/try/prepper_docs.py"
  for py in "$SPY" "$VPY"; do
    log="$W/imp-$(basename "$py").log"
    ( cd "$W/try" && PYTHONDONTWRITEBYTECODE=1 timeout 120 "$py" -c 'import dashboard' ) > "$log" 2>&1 || { tail -n 40 "$log"; stop "Import dashboard mit $py fehlgeschlagen"; }
    if grep -q "audioKern Selbsttest FEHLER" "$log"; then tail -n 30 "$log"; stop "audioKern-Selbsttest fehlgeschlagen ($py)"; fi
    grep -q "Stimme mb-de7 nur mit lokaler Datei" "$log" || { tail -n 20 "$log"; stop "Stimmtest fehlt ($py)"; }
    grep -q "teil4 selftest ok" "$log" || stop "teil4-Selbsttest fehlt ($py)"
    grep -q "usvAlarm ok" "$log" || stop "usvAlarm-Selbsttest fehlt ($py)"
    grep -q "usvShutdown ok" "$log" || stop "usvShutdown-Selbsttest fehlt ($py)"
  done
  echo "OK Import-Selbsttest mit Ersatzprozessen: mb-de7, Fehler, Zeitlimit, Abbruch, espeak-Rueckfall; teil4 und USV unveraendert ($SPY und $VPY). Keine echte Wiedergabe."
}
voice_import
code() { local c; c=$("${CURL[@]}" "$@" -o /dev/null -w "%{http_code}" || true); [[ -z "$c" ]] && c=000; echo "$c"; }
code_r() { local c i; for i in 1 2 3 4 5; do c=$(code "$@"); [[ "$c" == 200 ]] && break; sleep "${C61_RETRY_S:-6}"; done; echo "$c"; }
PAGES=(/ /speicher /funk /pi /umwelt /funk433 /aprs /meteor /rundfunk /energie /dabhist /mesh /karte /lokale-energie)
APIS=(/api/sdr/ui /api/sdr/wd /api/br24 /api/sdr/sticktest /api/sdr/live /api/sdr/map /api/broadcast/events /api/t2/status /api/t3/status /api/t4/status /api/t4/map /api/t4/tii /api/meteor /api/sdr/status /api/usv /api/docs/list)
declare -A PRE
for p in "${PAGES[@]}" "${APIS[@]}"; do PRE[$p]=$(code -L --max-redirs 5 "$B$p"); done
echo "vorher HTTP: $(for p in "${PAGES[@]}" "${APIS[@]}"; do printf '%s=%s ' "$p" "${PRE[$p]}"; done)"
for u in prepper-dashboard; do a=$(systemctl is-active "$u" 2>/dev/null || true); [[ "$a" == active ]] || { [[ "$DRY" == 1 ]] && echo "HINWEIS Dienst $u ist nicht aktiv ($a)" || stop "Dienst $u ist nicht aktiv ($a)"; }; done
SVCS="prepper-dashboard prepper-sdr mesh-bridge mesh-bridge-bayern"
declare -A ACT0 AET0
for u in $SVCS; do ACT0[$u]=$(systemctl is-active "$u" 2>/dev/null || true); AET0[$u]=$(systemctl show -p ActiveEnterTimestamp --value "$u" 2>/dev/null || true); done
echo "Dienste vorher: $(for u in $SVCS; do printf '%s=%s ' "$u" "${ACT0[$u]}"; done)"
OURS=" dashboard.py prepper_docs.py "
others() { local f b; for f in "$DASH_DIR"/*.py; do b=$(basename "$f"); [[ "$OURS" == *" $b "* ]] || echo "$b $(s16 "$f")"; done; }
others > "$W/others0.txt"
ready_voice() {
  local limit="${C61_READY_S:-180}" pause t0 now elapsed hc line pyrc cf
  [[ "$limit" =~ ^[0-9]+$ ]] || limit=180
  t0=$(date +%s)
  mkdir -p "$W/html"
  : > "$W/voice-wait.log"
  while true; do
    now=$(date +%s); elapsed=$((now - t0))
    if (( elapsed >= limit )); then
      echo "FAIL Zeit ${limit}s: Seite noch Startbildschirm oder ohne Stimme/USV" | tee -a "$W/voice-wait.log"
      return 1
    fi
    if ! systemctl is-active --quiet prepper-dashboard; then
      echo "WAIT ${elapsed}s Dienst nicht aktiv" | tee -a "$W/voice-wait.log"
    else
      cf="$W/html/pi-try.html"
      hc=$("${CURL[@]}" -o "$cf" -w "%{http_code}" "$B/pi" || true)
      [[ -z "$hc" ]] && hc=000
      sf="$W/html/au-try.json"
      ac=$("${CURL[@]}" -o "$sf" -w "%{http_code}" "$B/api/audio/status" || true)
      [[ -z "$ac" ]] && ac=000
      lf="$W/html/usv-try.html"
      lc=$("${CURL[@]}" -o "$lf" -w "%{http_code}" "$B/lokale-energie" || true)
      [[ -z "$lc" ]] && lc=000
      set +e
      line=$(python3 - "$cf" "$hc" "$sf" "$ac" "$lf" "$lc" << 'PY'
import sys
pi_p, pi_c, au_p, au_c, us_p, us_c = sys.argv[1:7]
def rd(p):
    try:
        return open(p, encoding="utf-8", errors="replace").read()
    except Exception:
        return ""
pi, au, us = rd(pi_p), rd(au_p), rd(us_p)
hard = ("Traceback (most recent call last)", "jinja2.exceptions", "UndefinedError", "TemplateSyntaxError", "Internal Server Error")
blob = pi + "\n" + au + "\n" + us
hit = [s for s in hard if s in blob]
if pi_c == "500" or au_c == "500" or us_c == "500" or hit:
    print("FAIL HTTP %s/%s/%s Vorlage oder Laufzeit: %s" % (pi_c, au_c, us_c, ", ".join(hit) or "HTTP 500"))
    sys.exit(2)
boot = "Dashboard startet" in pi or "Dashboard startet" in us
need_au = ("mbrola-de7", "nicht von diesem Patch installiert")
need_us = ("USV SPITZBODEN", "USV EG", "nicht verbunden")
miss = [s for s in need_au if s not in au] + [s for s in need_us if s not in us]
if "audioBox" not in pi and "Lautsprecher" not in pi:
    miss.append("Audio-Kachel")
if not miss and not boot and pi_c == "200" and au_c == "200" and us_c == "200":
    print("READY HTTP 200 echte Seite, Stimme mb-de7 im Status, USV-Kacheln, kein Startbildschirm")
    sys.exit(0)
why = []
if boot:
    why.append("Startbildschirm")
if pi_c != "200" or au_c != "200" or us_c != "200":
    why.append("HTTP %s/%s/%s" % (pi_c, au_c, us_c))
if miss:
    why.append("fehlt: " + ", ".join(miss))
print("WAIT " + ("; ".join(why) or "unvollstaendig"))
sys.exit(1)
PY
)
      pyrc=$?
      set -e
      echo "$line" | tee -a "$W/voice-wait.log"
      if [[ "$pyrc" -eq 0 ]]; then cp -f "$cf" "$W/html/pi1.html"; echo "OK Seiten bereit nach ${elapsed}s"; return 0; fi
      if [[ "$pyrc" -eq 2 ]]; then return 2; fi
    fi
    pause="${C61_WAIT_S:-2}"; sleep "$pause"
  done
}
if [[ "$STATE" == neu ]]; then
  ready_voice && rc=0 || rc=$?
  if [[ "$rc" -eq 0 ]]; then
    [[ "$(sfull "$DASH_DIR/lage_pages.py")" == "$LH0" ]] || stop "lage_pages.py hat sich veraendert"
    FINISHED=1
    echo "OK $MK laeuft schon (Variante $VARIANT) - nichts geaendert, kein Neustart"
    echo "COMMIT $COMMIT_ARG stimmede=1 fertig (schon installiert, nichts geaendert) variante=$VARIANT lage=${LH0:0:16}"
    exit 0
  fi
  cat "$W/voice-wait.log"
  stop "$NM ist in den Dateien installiert, aber die echte Seite zeigt Stimme oder USV nicht."
fi
rswin() { local m=$(( $1 / 60 % 60 )); [[ $m -ge 55 || $m -lt 5 ]]; }
rssec() { local hm
  if [[ -n "${C61_FAKE_HM:-}" && "$SIM" == 1 ]]; then hm="$C61_FAKE_HM"; echo $(( 10#${hm%%:*} * 3600 + 10#${hm##*:} * 60 + $1 )); return; fi
  echo $(( 10#$(TZ=Europe/Berlin date +%H) * 3600 + 10#$(TZ=Europe/Berlin date +%M) * 60 + 10#$(TZ=Europe/Berlin date +%S) + $1 )); }
rshm() { printf '%02d:%02d' $(( $1 / 3600 % 24 )) $(( $1 / 60 % 60 )); }
rscheck() { local s0 s1; s0=$(rssec 0); s1=$(rssec 300)
  if rswin "$s0" || rswin "$s1"; then
    if [[ "$DRY" == 1 ]]; then echo "HINWEIS Neustart-Sperre: jetzt ($1, $(rshm "$s0") Uhr Berlin) waere ein echter Lauf gesperrt (HH:50 bis HH:04 inklusive) - frei ab HH:05"
    else stop "Neustart-Sperre: es ist $(rshm "$s0") Uhr (Berlin) - Sperre HH:50 bis HH:04 inklusive - prepper-dashboard wird jetzt nicht neu gestartet; bitte ab HH:05 erneut starten"; fi
  else echo "OK Neustart-Sperre: $(rshm "$s0") Uhr (Berlin) liegt ausserhalb HH:50 bis HH:04, auch in 5 min ($1)"; fi; }
rscheck "Vorpruefung"
if [[ "$DRY" == 1 ]]; then
  FINISHED=1
  echo "TROCKENLAUF fertig - nichts installiert, kein apt, kein Neustart, nichts gesendet. Variante $VARIANT, lage_pages.py ${LH0:0:16} unangetastet."
  echo "COMMIT $COMMIT_ARG stimmede=dry fertig"
  exit 0
fi
sudo -v || stop "sudo -v fehlgeschlagen (Passwort noetig?)"
waitd() { local i; for i in $(seq 1 80); do sleep "${C61_WAIT_S:-3}"; systemctl is-active --quiet prepper-dashboard && [[ "$(code "$B/")" == 200 ]] && return 0; done; return 1; }
rb() {
  set +e +o pipefail
  trap - ERR
  RB_DONE=1
  echo "ROLLBACK: $1"
  local x
  for x in "${INST[@]}"; do [[ -f "$x.bak-$NM-$TS" ]] && cp -a "$x.bak-$NM-$TS" "$x.rb" && mv -f "$x.rb" "$x"; done
  for x in "${INST[@]}"; do [[ -f "$x.bak-$NM-$TS" ]] && { cmp -s "$x" "$x.bak-$NM-$TS" && echo "  $(basename "$x") = Sicherung ($(s16 "$x"))" || echo "  WARNUNG $(basename "$x") ungleich Sicherung"; }; done
  [[ "$(sfull "$DASH_DIR/lage_pages.py")" == "$LH0" ]] && echo "  lage_pages.py unveraendert (${LH0:0:16})" || echo "  WARNUNG lage_pages.py veraendert"
  if [[ "$RESTARTED" == 1 ]]; then sudo systemctl restart prepper-dashboard.service 9>&-; waitd; fi
  echo "alter Stand wieder aktiv: prepper-dashboard=$(systemctl is-active prepper-dashboard 2>/dev/null), HTTP / = $(code "$B/")"
  echo "  upsmon, killpower, Firewall, Mesh und Paketquellen wurden nicht veraendert; nichts gesendet"
}
rbx() { rb "$1"; exit 1; }
rscheck "unmittelbar vor dem Ersetzen"
PHASE=installiert
for f in "${SINGLE[@]}"; do
  x="$DASH_DIR/$f"
  cp -a "$x" "$x.bak-$NM-$TS"
  cmp -s "$x" "$x.bak-$NM-$TS" || rbx "Sicherung $f ungleich Original"
  { ls -1t "$x.bak-$NM-"* 2>/dev/null || true; } | tail -n +$((KEEP_LAST + 1)) | while read -r o; do rm -f -- "$o"; done
done
echo "OK Sicherungen *.bak-$NM-$TS (behalten: letzte $KEEP_LAST)"
for f in "${SINGLE[@]}"; do
  x="$DASH_DIR/$f"; INST+=("$x")
  cp "$W/neu/$f" "$x.new" && chmod --reference="$x.bak-$NM-$TS" "$x.new" && mv -f "$x.new" "$x" || { rm -f "$x.new"; rbx "$f installieren"; }
  [[ "$(sfull "$x")" == "${NEU[$f]}" ]] || rbx "$f nach dem Kopieren falsch"
done
[[ "$(sfull "$DASH_DIR/lage_pages.py")" == "$LH0" ]] || rbx "lage_pages.py wurde veraendert"
[[ "$(sfull "$DASH_DIR/ups_manager.py")" == "$UPS_KEEP" ]] || rbx "ups_manager.py wurde veraendert"
echo "OK zwei Dateien atomar ersetzt; lage_pages.py Variante $VARIANT bleibt ${LH0:0:16}"
for py in "$SPY" "$VPY"; do
  for f in "${SINGLE[@]}"; do
    "$py" -W error -c 'import sys; compile(open(sys.argv[1], encoding="utf-8").read(), sys.argv[1], "exec")' "$DASH_DIR/$f" 2>"$W/pyc.log" || { cat "$W/pyc.log"; rbx "py_compile $f mit $py"; }
  done
done
RESTARTED=1
echo "Neustart prepper-dashboard (nur dieser Dienst) - warte auf die echte Seite (max ${C61_READY_S:-180} s). Kein apt."
sudo systemctl restart prepper-dashboard.service 9>&-
ready_voice && rc=0 || rc=$?
if [[ "$rc" -ne 0 ]]; then cat "$W/voice-wait.log"; rbx "Seite nach dem Neustart nicht bereit"; fi
for p in "${PAGES[@]}" "${APIS[@]}"; do
  c=$(code_r -L --max-redirs 5 "$B$p")
  [[ "$c" == "${PRE[$p]}" ]] || rbx "$p antwortet $c (vorher ${PRE[$p]})"
done
echo "OK Smoke-Test: ${#PAGES[@]} Seiten und ${#APIS[@]} APIs antworten wie vorher"
others > "$W/others1.txt"; cmp -s "$W/others0.txt" "$W/others1.txt" || rbx "andere Programmdateien haben sich veraendert"
for u in $SVCS; do
  [[ "$u" == prepper-dashboard ]] && continue
  a=$(systemctl is-active "$u" 2>/dev/null || true); t=$(systemctl show -p ActiveEnterTimestamp --value "$u" 2>/dev/null || true)
  [[ "$a" == "${ACT0[$u]}" && "$t" == "${AET0[$u]}" ]] || rbx "Dienst $u hat sich veraendert"
done
[[ "$(sfull "$DASH_DIR/lage_pages.py")" == "$LH0" ]] || rbx "lage_pages.py am Ende veraendert"
echo "OK nur prepper-dashboard neu gestartet; prepper-sdr und Mesh unveraendert; kein apt; nichts gesendet"
PHASE=fertig
FINISHED=1
echo "COMMIT $COMMIT_ARG stimmede=1 fertig dashboard=${NEU[dashboard.py]:0:16} prepper_docs=${NEU[prepper_docs.py]:0:16} lage_pages=${LH0:0:16} ups_manager=${UPS_KEEP:0:16} variante=$VARIANT"
